	private static Union scopedUnion(TupleExpr left, TupleExpr right) {
		Union union = new Union(left, right);
		union.setVariableScopeChange(true);
		return union;
	}

	private static Union optionalUnion(QueryRoot expression, boolean left) {
		LeftJoin optional = (LeftJoin) expression.getArg();
		return (Union) (left ? optional.getLeftArg() : optional.getRightArg());
	}

	private static BindingSetAssignment values(String name, BindingSet... rows) {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of(name));
		values.setBindingSets(List.of(rows));
		return values;
	}

	private static BindingSet row(String name, Value value) {
		return new ListBindingSet(List.of(name), value);
	}

	private static StatementPattern statement(String predicate) {
		return new StatementPattern(Var.of("x"),
				Var.of("predicate", VALUES.createIRI(predicate), true, true), Var.of("object"));
	}

	private static List<Map<String, Value>> evaluate(TupleExpr expression, BindingSet input) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		List<Map<String, Value>> results = new ArrayList<>();
		// Preparation annotates algorithms; keep those annotations out of the optimizer's input trees.
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression.clone(), input)) {
			while (iteration.hasNext()) {
				BindingSet bindings = iteration.next();
				Map<String, Value> row = new HashMap<>();
				for (String name : bindings.getBindingNames()) {
					Value value = bindings.getValue(name);
					if (value != null) {
						row.put(name, value);
					}
				}
				results.add(Map.copyOf(row));
			}
		}
		return results;
	}

	private static int randomEvaluations(TupleExpr expression) {
		CountingRandomStrategy strategy = new CountingRandomStrategy();
		int rows = 0;
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression.clone(),
				EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				iteration.next();
				rows++;
			}
		}
		assertThat(rows).isEqualTo(2);
		return strategy.calls.get();
	}

	private static final class CountingRandomStrategy extends DefaultEvaluationStrategy {
		private final AtomicInteger calls = new AtomicInteger();

		private CountingRandomStrategy() {
			super(new EmptyTripleSource(), null);
		}

		@Override
		public QueryValueEvaluationStep prepare(FunctionCall function, QueryEvaluationContext context) {
			QueryValueEvaluationStep delegate = super.prepare(function, context);
			if (!"RAND".equals(function.getURI())) {
				return delegate;
			}
			return bindings -> {
				calls.incrementAndGet();
				return delegate.evaluate(bindings);
			};
		}
	}
